const contents = $input.all();
const body = $('Webhook').first().json.body;
const contentId = body.contentId;

// If a specific contentId is passed, focus ONLY on that one
if (contentId) {
  const specific = contents.filter(c => c.json._id === contentId);
  if (specific.length > 0) return specific;
}

// Otherwise, filter for all readable attachments in the lesson
const attachments = contents.filter(c => 
  (c.json.type === 'file' && c.json.url) || 
  (c.json.type === 'link' && c.json.url)
);
return attachments.map(f => ({
  json: f.json,
  pairedItem: f.pairedItem
}));

// Simple HTML to Text stripper
const html = $input.first().json.data || $input.first().text || "";
const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{ json: { text: text.substring(0, 10000) } }];

const lecon = $('Fetch Lecon').first().json;
const allContents = $('Fetch Contents').all().map(i => i.json);
const body = $('Webhook').first().json.body;
const action = body.action || 'explain';
const question = body.question || '';
const contentId = body.contentId;

// Collect text from all sources (PDFs and Scraped URLs)
let extractedText = "";
try {
  const pdfTexts = $('Extract PDF').all().map(f => f.json.text);
  const urlTexts = $('Clean HTML').all().map(f => f.json.text);
  extractedText = [...pdfTexts, ...urlTexts].join('\n\n---\n\n');
} catch (e) {
  extractedText = "No external content processed.";
}

let context = `LESSON TITLE: ${lecon.titre}\n`;
if (contentId) {
  const target = allContents.find(c => c._id === contentId);
  context += `TARGET CONTENT: ${target ? target.title : 'Specific content item'}\n`;
  context += `Note: The student is specifically asking about this item.\n\n`;
}

const safeText = extractedText.substring(0, 15000);
context += `--- EXTERNAL KNOWLEDGE ---\n${safeText}\n\n`;

return [{ json: { context, action, question, leconTitle: lecon.titre, isSpecific: !!contentId } }];
